    // 1. If customer is null or trip is null or bookingDate is null, return false.
    if (getCustomer() == null || getTrip() == null || getBookingDate() == null) {
      return false;
    }
    
    // 2. If trip.numberOfSeats - trip.getBookedSeats() < numberOfSeats, return false.
    Trip theTrip = getTrip();
    if (theTrip.getNumberOfSeats() - theTrip.getBookedSeats() < getNumberOfSeats()) {
      return false;
    }
    
    // 3. If this customer has any booking on the same day whose trip time interval overlaps
    //    with this trip's time interval (using departureTime and arrivalTime), return false.
    for (Booking existingBooking : getCustomer().getBookings()) {
      if (existingBooking != this && existingBooking.getTrip() != null) {
        if (overlapsWith(existingBooking.getTrip())) {
          return false;
        }
      }
    }
    
    // 4. Compute the difference between trip.departureTime and current system time.
    //    If the difference is less than or equal to 2 hours, return false.
    try {
      java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm");
      java.util.Date departureDateTime = sdf.parse(theTrip.getDepartureTime());
      java.util.Date now = new java.util.Date();
      long diffMillis = departureDateTime.getTime() - now.getTime();
      long twoHoursMillis = 2 * 60 * 60 * 1000L;
      if (diffMillis <= twoHoursMillis) {
        return false;
      }
    } catch (java.text.ParseException e) {
      return false;
    }
    
    // 5. Return true.
    return true;
